// The new deadline date for the task in ISO 8601 format (YYYY-MM-DD, e.g., "2025-12-31"). Deadlines are immovable constraints shown with a different indicator than due dates. Use "remove" to clear the deadline.
deadlineDate?: string,
// New additional details, notes, or context for the task. Use this for longer content rather than putting it in the task name. Supports Markdown.
description?: string,
// The new due date for the task in natural language (e.g., "tomorrow at 5pm"). Use "remove" to clear the due date. Replaces any recurrence, so it is refused on a recurring task unless replaceRecurrence is true. To move a task, use reschedule-tasks.
dueString?: string,
// The duration of the task. Use format: "2h" (hours), "90m" (minutes), "2h30m" (combined), "1.5h" (decimal hours), or "3d" (whole days; days cannot be combined with hours or minutes). Todoist apps only display durations under 24 hours: a longer or day-based duration is stored and reported by this server, but the apps show the task as having no duration.
duration?: string,
// The ID of the task to update.
id: string, // minLength: 1
// Whether this task should be uncompletable (organizational header). Tasks with isUncompletable: true appear as organizational headers and cannot be completed.
isUncompletable?: boolean,
// The new labels for the task. Replaces all existing labels.
labels?: string[], // maxItems: 50
// The new order of the task within its parent/section.
order?: number,
// Make the task a subtask of this task ID. Omit unless the parent should change.
parentId?: string,
// Task priority as a string: "p1" (highest), "p2" (high), "p3" (medium), or "p4" (lowest/default). Integers like 1, 2, 3, or 4 are not accepted.
priority?: "p1" | "p2" | "p3" | "p4",
// Move the task to this project ID, or the text "inbox" for the inbox. Omit unless the project should change: moving a task to a project also lifts it out of its section and out from under its parent.
projectId?: string,
// True only when the user asks to change or drop a recurring task's recurrence rule.
replaceRecurrence?: boolean,
// Change task assignment. Use "unassign" to remove assignment. Can be "me" (assigns to current user), a user ID, name, or email. User must be a project collaborator.
responsibleUser?: string,
// Move the task to this section ID. Omit unless the section should change: moving a task to a section also lifts it out from under its parent.
sectionId?: string,
}
>,
}): Promise<{
// Summary of operations performed.
appliedOperations: {
failureCount: number,
// Moves not performed because the task was already in the requested destination. A non-zero count means container fields were sent that did not need to be.
redundantMovesSkipped: number,
// The number of tasks skipped (no changes).
skippedCount: number,
// The number of tasks actually updated.
updateCount: number,
},
// Tasks that could not be updated, with the reason for each.
failures: Array<
{
code?: string,
error: string,
// Usually the ID of the item that failed.
item: string,
}
>,
// The updated tasks.
tasks: Array<
{
// ISO 8601.
addedAt?: string,
assignedByUid?: string,
// Whether the task is completed.
checked: boolean,
// ISO 8601.
completedAt?: string,
// Task title.
content: string,
// ISO 8601.
deadlineDate?: string,
description: string,
// ISO 8601.
dueDate?: string,
// e.g. "2h30m", or "3d" for a day-based duration.
duration?: string,
id: string,
// True when deleted; absent otherwise.
isDeleted?: boolean,
// An organizational header, not a real task.
isUncompletable?: boolean,
labels?: string[],
parentId?: string,
// p1 is highest, p4 lowest.
priority: "p1" | "p2" | "p3" | "p4",
projectId: string,
// False when not recurring, otherwise the recurrence string.
recurring: boolean | string,
responsibleUid?: string,
sectionId?: string,
}
>,
// The total number of tasks updated.
totalCount: number,
// The IDs of the updated tasks.
updatedTaskIds: string[],
}>;
```

