//
// Input for the tools that address a single domain. The owning account is derived from domain_id.
{
// Id of the domain, as returned by list_domains or create_domain.
domain_id: string,
// DomainProduct
//
// Product the domain belongs to.
product: "pages" | "forms",
}): Promise<// DomainSetupLinkToolOutput
{
// Id of the domain the link was issued for.
