{
// Human-readable description of the dimension, as returned by insights-public_discover. Pass null when constructing a dimension reference manually.
description?: string | null,
// Dimension name as returned by insights-public_discover for the selected field.
name: string,
}
>,
// Field ID to rank: a form field ID, or a study question's ref. Null for the usability matrix or the contacts dataset.
field_id?: string | null,
// Cross-field filter conditions. Null for no filtering.
filters?:
 | null
// Top-level filter structure grouping conditions with a logical operator.
 | {
// Logical operator joining filter groups.
conditional: "and" | "or",
// Groups of filter conditions.
