any // $ref: "#/$defs/MCPFilterGroup"
>,
}
,
// Form ID selecting the "forms" dataset. Value when scoping to a form; null otherwise. Mutually exclusive with audience_id and study_id.
form_id?: string | null,
// Maximum number of ranked rows to return. Integer between 1 and 100.
limit: integer, // minimum: 1, maximum: 100
// Measure names to compute per group (e.g. "count", "average", "nps_score"). Call insights-public_discover first to learn which measures each field supports.
// minItems: 1
measures: Array<
// A measure name supported by the selected field.
string
>,
// Property ID to rank. Required together with audience_id for the "contacts" dataset; null otherwise.
property_id?: string | null,
// Sort order applied to the ranked groups. Null for no explicit order (rows come back in unspecified group order).
