// ID of the page to fetch.
page_id: string,
}): Promise<{
page: {
// ID of the account that owns this page.
account_id: string,
// When the page was created.
created_at: string, // format: "date-time"
// Unique page identifier.
id: string,
links: {
// Region-aware admin URL where the page is edited in the builder (e.g. https://admin.typeform.com/accounts/{accountId}/pages/{id}/create). Present whether or not the page is live. Null when link resolution fails. Use verbatim; do not construct this URL from page or variant IDs.
builder: string | null,
// Active custom-domain URL. Null when the page is not live, when no active custom-domain route exists, or when link resolution fails.
custom_domain: string | null,
// Default subdomain URL (e.g. https://page.typeform.com/p/{id}). Null only when link resolution fails entirely.
default: string | null,
// The highest-precedence public URL available for this page. Null when the page has no published revision (i.e. the page is not yet live), or when link resolution fails.
display: string | null,
},
// Human-readable page title.
title: string,
// When the page was last updated.
updated_at: string, // format: "date-time"
// ID of the workspace this page belongs to.
workspace_id: string,
},
publication: {
// The default variant this publication state describes.
default_variant_id: string,
// True when the draft has edits newer than the live revision (status changed).
has_unpublished_changes: boolean,
// True when the page has a published revision (status published or changed).
is_live: boolean,
// The revision visitors see. Null while the page is not live.
live_revision_number: integer | null,
// empty_draft: nothing to publish yet. draft: never published. published: live with no newer edits. changed: live, with unpublished edits.
status: "empty_draft" | "draft" | "published" | "changed",
},
}>;
```

