[key: string]: object,
},
layout: {
// Responsive overrides per breakpoint.
breakpoints?: { [key: string]: any },
// Ordered list of layout nodes defining the page structure.
root?: any[],
},
// Optional SEO and social metadata used to emit <title>, <meta description>, og:* and robots tags on the published page. All sub-fields are optional.
metadata?: {
// Used for <meta description> and og:description.
description?: string,
// Favicon image (clafoutis CDN allowlist).
favicon_url?: string,
// Drives the robots index/noindex directive.
show_in_search_results?: boolean, // default: true
// Used for og:site_name and shown in the social preview card.
site_name?: string,
// Open Graph social image, typically 1200x630 (clafoutis CDN allowlist).
social_image_url?: string,
// Used for the <title> tag and og:title. Falls back to the page title (page.title) when unset.
title?: string,
},
settings?: {
// Whether to hide the Typeform branding.
hide_typeform_branding?: boolean, // default: false
},
// Page-level style overrides.
style?: {
// Per-block style overrides keyed by block ID.
blocks?: { [key: string]: any },
global?: { [key: string]: any },
},
// The page theme applied to the variant.
theme: {
// ID of the page theme. The stored theme link is internal and is not exposed by the public tools.
id: string | null,
},
},
// schema.org WebPage JSON-LD metadata generated from the page content at publish time. Contains structured data for SEO and rich results.
jsonld: { [key: string]: any },
